import Quill from 'quill';
import 'quill/dist/quill.snow.css'; // Quill's default theme

export default class TextBlockTool {
  static get toolbox() {
    return {
      title: 'Text Block',
      icon: '<svg width="20" height="20" viewBox="0 0 20 20"><path d="M3 3h14v2H3V3zm0 4h14v2H3V7zm0 4h14v2H3v-2zm0 4h14v2H3v-2z"/></svg>',
    };
  }

  constructor({ data, api }) {
    this.data = {
      content: data.content || '',
    };
    this.api = api;
    this.wrapper = null;
    this.quill = null;
  }

  render() {
    this.wrapper = document.createElement('div');
    this.wrapper.classList.add('text-block-tool');

    // Quill editor container
    const editor = document.createElement('div');
    editor.classList.add('text-block-editor');
    this.wrapper.appendChild(editor);

    // Initialize Quill
    this.quill = new Quill(editor, {
      theme: 'snow',
      modules: {
        toolbar: [
          ['bold', 'italic', 'underline'], // Text styles
          [{ 'color': [] }, { 'background': [] }], // Text and background color
          [{ 'size': ['small', false, 'large', 'huge'] }], // Font size
          [{ 'list': 'ordered' }, { 'list': 'bullet' }], // Lists
          ['clean'], // Remove formatting
        ],
      },
      formats: [
        'bold', 'italic', 'underline',
        'color', 'background',
        'size',
        'list', 'bullet',
      ],
      placeholder: 'Paste or type your text here...',
    });

    // Set initial content
    if (this.data.content) {
      this.quill.root.innerHTML = this.data.content;
    }

    // Update data on change
    this.quill.on('text-change', () => {
      this.data.content = this.quill.root.innerHTML;
    });

    return this.wrapper;
  }

  save() {
    return {
      content: this.data.content,
    };
  }

  static get isReadOnlySupported() {
    return true;
  }

  renderSettings() {
    const settingsWrapper = document.createElement('div');

    // Option to clear content
    const clearButton = document.createElement('button');
    clearButton.textContent = 'Clear Text';
    clearButton.style.margin = '5px';
    clearButton.addEventListener('click', () => {
      this.quill.root.innerHTML = '';
      this.data.content = '';
    });
    settingsWrapper.appendChild(clearButton);

    return settingsWrapper;
  }
}