<template>
    <div class="note-item-container">
        <div class="note-item-row" :style="{ paddingLeft: `${level * 20}px` }">
            <span @click="toggleChildren" style="cursor: pointer;">
                {{ isOpen ? '🔽' : '▶️' }}
            </span>
            <span
                @click="toggleShowDetails"
                style="cursor: pointer; margin-left: 5px;"
                :class="{ 'highlighted': note.id === activeNoteId }"
            >
                {{ note.attributes.name }}
            </span>
            <v-btn
                v-if="showDeleteButtons"
                icon
                x-small
                color="error"
                @click="$emit('deleteNote', note.id)"
                class="custom-delete-btn"
            >
                <v-icon style="font-size: 14px;">mdi-delete</v-icon>
            </v-btn>
        </div>

        <div v-if="isOpen" class="note-children">
            <NoteItem
                v-for="child in note.attributes.child_ids?.data || []"
                :key="child.id"
                :note="child"
                :parentName="note.attributes.name"
                :level="level + 1"
                :activeNoteId="activeNoteId"
                :onSave="onSave"
                :showDeleteButtons="showDeleteButtons"
                @updateActiveNote="updateActiveNote"
                @deleteNote="$emit('deleteNote', $event)"
            />
        </div>

        <div v-if="note.id === activeNoteId && loaded" class="sidebar">
            <h1>{{ parentName || '' }}</h1>
            <EnhancedEditor :key="note.attributes.block" ref="editorRef" :initialData="pdata()" />
            <v-btn
                @click="saveContact"
                color="primary"
                class="mx-1"
                rounded
                style="width: 10%; min-width: 10px; height: 36px;"
            >
                Save
            </v-btn>
        </div>

        <viewProject v-if="showProjectView" :projectName="projectName" />
    </div>
</template>

<script>
import { ref, watch } from 'vue';
import EnhancedEditor from './EnhancedEditor.vue';
import { loadContacts } from '@/utils/contactUtils';
import cloneDeep from 'lodash/cloneDeep';
import viewProject from './powerView.vue';

export default {
    components: {
        EnhancedEditor,
        viewProject
    },
    props: {
        note: {
            type: Object,
            required: true
        },
        level: {
            type: Number,
            default: 0
        },
        activeNoteId: {
            type: String,
            required: true
        },
        parentName: {
            type: String,
            default: ''
        },
        onSave: Function,
        showDeleteButtons: {
            type: Boolean,
            default: false
        }
    },
    setup(props, { emit }) {
        const editorRef = ref(null);
        const isOpen = ref(false);
        const blockContent = ref({});
        const loaded = ref(false);
        const contacts = ref([]);
        const projectName = ref('My Project');
        const showProjectView = ref(false);

        watch(() => props.showDeleteButtons, (newValue) => {
            console.log('NoteItem showDeleteButtons:', newValue, 'for note:', props.note.attributes.name);
        });

        const toggleChildren = () => {
            isOpen.value = !isOpen.value;
        };

        if (props.note.attributes.type === 'h') {
            loaded.value = false;
        } else {
            loaded.value = true;
        }

        const pdata = () => {
            let dupBlock = [];
            console.log('Block data:', props.note.attributes.block);

            if (props.note.attributes.block) {
                const blockData = cloneDeep(props.note.attributes.block);
                if (Array.isArray(blockData.blocks)) {
                    dupBlock = blockData.blocks;
                } else if (Array.isArray(blockData)) {
                    dupBlock = blockData;
                } else {
                    console.warn('Unexpected block structure:', blockData);
                    dupBlock = [];
                }
            }

            if (Array.isArray(dupBlock)) {
                for (let ii = 0; ii < dupBlock.length; ii++) {
                    if (dupBlock[ii].data) {
                        dupBlock[ii].data.rows = contacts.value;
                        dupBlock[ii].data.parentName = props.parentName;
                    }
                }
            } else {
                console.error('dupBlock is not an array:', dupBlock);
                dupBlock = [];
            }

            const result = {
                time: 1729030092472,
                blocks: dupBlock,
                version: '2.30.6'
            };
            console.log('pdata result:', result);
            return result;
        };

        const fetchData = async () => {
            console.log('load data...');
            contacts.value = await loadContacts(props.parentName, 0);
            if (contacts.value) {
                loaded.value = true;
            }
        };

        const toggleShowDetails = () => {
            if (props.note.id === props.activeNoteId) {
                emit('updateActiveNote', null);
                loaded.value = false;
            } else {
                if (props.note.attributes.type === 'p') {
                    toggleProjectView();
                } else {
                    emit('updateActiveNote', props.note.id);
                }
                if (!loaded.value) {
                    fetchData();
                }
            }
        };

        const saveTaskToContact = async () => {
            try {
                const savedData = await editorRef.value.getSavedData();
                console.log('Data to save to server:', savedData);
                blockContent.value = savedData;
            } catch (error) {
                console.error('Failed to get saved data:', error);
            }
        };

        const saveContact = async () => {
            await saveTaskToContact();
            props.onSave(props.note.id, blockContent.value);
        };

        const updateActiveNote = (noteId) => {
            emit('updateActiveNote', noteId);
        };

        const toggleProjectView = () => {
            showProjectView.value = !showProjectView.value;
            if (showProjectView.value) {
                projectName.value = props.parentName;
            }
        };

        return {
            editorRef,
            isOpen,
            toggleChildren,
            toggleShowDetails,
            updateActiveNote,
            saveContact,
            fetchData,
            loaded,
            pdata,
            projectName,
            toggleProjectView,
            showProjectView
        };
    }
};
</script>

<style scoped>
.highlighted {
    background-color: yellow;
    font-weight: bold;
    transition: background-color 0.3s;
}

.note-item-row {
    display: flex;
    align-items: center;
    padding: 4px 0;
}

.note-children {
    margin-left: 20px;
}

.custom-delete-btn {
    width: 20px !important;
    height: 20px !important;
}

.custom-delete-btn .v-icon {
    font-size: 14px !important;
}
</style>