export default class CodeBlockTool {
  static get toolbox() {
    return {
      title: 'Code Block',
      icon: '<svg width="20" height="20" viewBox="0 0 20 20"><path d="M5 6l5 5-5 5V6zm10 0l-5 5 5 5V6z"/></svg>',
    };
  }

  constructor({ data, api }) {
    this.data = {
      code: typeof data.code === 'string' ? data.code : '',
      language: data.language || 'javascript',
      codeHidden: data.codeHidden !== undefined ? data.codeHidden : true, // Default to hidden code
      editorHidden: data.editorHidden !== undefined ? data.editorHidden : true, // Default to hidden editor
    };
    this.api = api;
    this.wrapper = null;
    this.languages = ['javascript', 'python', 'html', 'css', 'java', 'cpp'];
    this.isReadOnly = false;
  }

  render() {
    console.log('CodeBlockTool render - data:', JSON.stringify(this.data));
    this.wrapper = document.createElement('div');
    this.wrapper.classList.add('code-block-tool');
    this.wrapper.classList.add(this.isReadOnly ? 'read-only' : 'editable');
    
    // Create a separate container for the code display area
    const codeContainer = document.createElement('div');
    codeContainer.classList.add('code-display-container');
    
    // Code View Toggle Button
    const codeToggleButton = document.createElement('button');
    codeToggleButton.classList.add('code-block-toggle', 'code-view-toggle');
    codeToggleButton.textContent = this.data.codeHidden ? 'Show Code' : 'Hide Code';
    codeToggleButton.setAttribute('type', 'button');
    codeContainer.appendChild(codeToggleButton);
    
    // Code View Content
    const codeContent = document.createElement('div');
    codeContent.classList.add('code-block-content', 'code-view-content');
    if (this.data.codeHidden) {
      codeContent.classList.add('hidden');
    }
    
    // Pre/code elements for syntax highlighting
    const pre = document.createElement('pre');
    const code = document.createElement('code');
    code.className = `language-${this.data.language}`;
    code.textContent = this.data.code || '// Enter your code here';
    pre.appendChild(code);
    codeContent.appendChild(pre);
    
    // Language selector for code view
    const codeSelect = document.createElement('select');
    codeSelect.classList.add('code-language-select');
    this.languages.forEach((lang) => {
      const option = document.createElement('option');
      option.value = lang;
      option.textContent = lang.charAt(0).toUpperCase() + lang.slice(1);
      if (lang === this.data.language) option.selected = true;
      codeSelect.appendChild(option);
    });
    codeSelect.addEventListener('change', (e) => {
      this.data.language = e.target.value;
      code.className = `language-${this.data.language}`;
      this._highlightCode(code);
    });
    codeContent.appendChild(codeSelect);
    
    codeContainer.appendChild(codeContent);
    this.wrapper.appendChild(codeContainer);
    
    // Create a separate container for the editor area
    const editorContainer = document.createElement('div');
    editorContainer.classList.add('editor-container');
    
    // Editor Toggle Button
    const editorToggleButton = document.createElement('button');
    editorToggleButton.classList.add('code-block-toggle', 'editor-toggle');
    editorToggleButton.textContent = this.data.editorHidden ? 'Show Editor' : 'Hide Editor';
    editorToggleButton.setAttribute('type', 'button');
    editorContainer.appendChild(editorToggleButton);
    
    // Editor Content
    const editorContent = document.createElement('div');
    editorContent.classList.add('code-block-content', 'editor-content');
    if (this.data.editorHidden) {
      editorContent.classList.add('hidden');
    }
    
    if (!this.isReadOnly) {
      // Create textarea for code editing
      const textarea = document.createElement('textarea');
      textarea.classList.add('code-block-textarea');
      textarea.value = this.data.code || '// Enter your code here';
      
      // Always keep textarea hidden by default
      if (this.data.editorHidden) {
        textarea.style.display = 'none';
      }
      
      textarea.style.cssText = `
        width: calc(100% - 20px);
        min-width: 200px;
        min-height: 100px;
        font-family: 'Courier New', Courier, monospace;
        font-size: 14px;
        line-height: 1.5;
        background: transparent;
        border: 1px solid #ccc;
        border-radius: 4px;
        padding: 10px;
        margin-bottom: 8px;
        resize: both;
        white-space: pre-wrap;
        box-sizing: border-box;
        outline: none;
      `;
      
      // Update code when textarea changes
      textarea.addEventListener('input', (e) => {
        this.data.code = e.target.value;
        code.textContent = e.target.value;
        this._highlightCode(code);
      });
      
      editorContent.appendChild(textarea);
    }
    
    editorContainer.appendChild(editorContent);
    this.wrapper.appendChild(editorContainer);
    
    // Highlight code initially
    this._highlightCode(code);
    
    // Set up code view toggle button event
    codeToggleButton.addEventListener('click', () => {
      this.data.codeHidden = !this.data.codeHidden;
      codeToggleButton.textContent = this.data.codeHidden ? 'Show Code' : 'Hide Code';
      codeContent.classList.toggle('hidden', this.data.codeHidden);
    });
    
    // Set up editor toggle button event
    editorToggleButton.addEventListener('click', () => {
      this.data.editorHidden = !this.data.editorHidden;
      editorToggleButton.textContent = this.data.editorHidden ? 'Show Editor' : 'Hide Editor';
      editorContent.classList.toggle('hidden', this.data.editorHidden);
      
      // Explicitly toggle textarea visibility
      const textarea = editorContent.querySelector('.code-block-textarea');
      if (textarea) {
        textarea.style.display = this.data.editorHidden ? 'none' : 'block';
      }
    });
    
    return this.wrapper;
  }

  _highlightCode(codeElement) {
    if (typeof window !== 'undefined' && window.Prism) {
      Prism.highlightElement(codeElement);
    }
  }

  renderSettings() {
    const settingsWrapper = document.createElement('div');
    
    // Clear code button
    const clearButton = document.createElement('button');
    clearButton.textContent = 'Clear Code';
    clearButton.style.margin = '5px';
    clearButton.addEventListener('click', () => {
      this.data.code = '';
      const textarea = this.wrapper.querySelector('textarea');
      const codeElement = this.wrapper.querySelector('code');
      if (textarea) {
        textarea.value = '// Enter your code here';
      }
      codeElement.textContent = '// Enter your code here';
      this._highlightCode(codeElement);
    });
    settingsWrapper.appendChild(clearButton);
    
    // Toggle read-only button
    const readOnlyButton = document.createElement('button');
    readOnlyButton.textContent = this.isReadOnly ? 'Enable Editing' : 'Make Read-Only';
    readOnlyButton.style.margin = '5px';
    readOnlyButton.addEventListener('click', () => {
      this.isReadOnly = !this.isReadOnly;
      this.api.blocks.render(this.data);
    });
    settingsWrapper.appendChild(readOnlyButton);
    
    return settingsWrapper;
  }

  save() {
    return {
      code: this.data.code,
      language: this.data.language,
      codeHidden: this.data.codeHidden,
      editorHidden: this.data.editorHidden
    };
  }

  static get isReadOnlySupported() {
    return true;
  }
}